// ?Rva002E3750SetModule@@YADDPBD@Z
// partial score=0.99 date=2026-09-10
// cl: /DNDEBUG /DWIN32 /MD /O2 /EHsc
//
// BFME's shared CurDrawableShowModule/CurDrawableHideModule helper at
// retail RVA 0x002E3750.  The two Lua registration wrappers at 0x002E3820
// and 0x002E3840 pass (on, text), and both tail into this body.  The object
// at 0x012F060C is the Lua drawable owner; its target is at +0x78 and that
// target's module owner is at +0x0c.  BfmeOwnerAE::bfmeSetAE is the matched
// name lookup/toggle callee at retail 0x00417CF0.

struct BfmeStrAE
{
	char *m_bfmeDataAE;
};

class BFMERetailAsciiString : public BfmeStrAE
{
public:
	BFMERetailAsciiString(const char *text);
	~BFMERetailAsciiString() { releaseBuffer(); }

private:
	void releaseBuffer();
};

class BfmeOwnerAE
{
public:
	char bfmeSetAE(BfmeStrAE *name, char on);
};

struct BfmeTargetBR
{
	char m_bfmePad[0x0c];
	BfmeOwnerAE *m_bfmeOwner;
};

struct BfmeOwnerBR
{
	char m_bfmePad[0x78];
	BfmeTargetBR *m_bfmeTarget;
};

extern BfmeOwnerBR *g_bfmeOwnerBR;

#pragma intrinsic(_ReadWriteBarrier)
extern "C" void _ReadWriteBarrier(void);

// ?Rva002E3750SetModule@@YADDPBD@Z
char Rva002E3750SetModule(char on, const char *text)
{
	if (g_bfmeOwnerBR->m_bfmeTarget != 0) {
		const BfmeTargetBR *target = g_bfmeOwnerBR->m_bfmeTarget;
		const char *nameText = *reinterpret_cast<const char * volatile *>(&text);
		BfmeOwnerAE *owner = target->m_bfmeOwner;
		BFMERetailAsciiString name(nameText);
		if (owner != 0) {
			_ReadWriteBarrier();
			return owner->bfmeSetAE(&name, on == 0);
		}
	}
	return 0;
}
